#include <bits/stdc++.h>
#include <chrono>
using namespace std; using namespace std::chrono;
static constexpr double GRID=1.0, COMM=0.07, TARGET=10.0, LEV=2000.0, FRI=20*3600+55*60;
bool parse(const string&l,int&date,int&sec,double&bid,double&ask){if(l.empty()||l[0]!='\"'||l.rfind("\"Exness\"",0)==0)return false;size_t c1=l.find(','),c2=l.find(',',c1+1),c3=l.find(',',c2+1),c4=l.find(',',c3+1);if(c4==string::npos)return false;string t=l.substr(c2+1,c3-c2-1);if(!t.empty()&&t.front()=='\"')t.erase(t.begin());if(!t.empty()&&t.back()=='\"')t.pop_back();if(t.size()<19)return false;date=stoi(t.substr(0,4))*10000+stoi(t.substr(5,2))*100+stoi(t.substr(8,2));sec=stoi(t.substr(11,2))*3600+stoi(t.substr(14,2))*60+stoi(t.substr(17,2));bid=strtod(l.c_str()+c3+1,nullptr);ask=strtod(l.c_str()+c4+1,nullptr);return bid>0&&ask>=bid;}
int wd(int d){int y=d/10000,m=(d/100)%100,dd=d%100;weekday w{sys_days{year{y}/month{(unsigned)m}/day{(unsigned)dd}}};return w.c_encoding();}
long long dn(int d){int y=d/10000,m=(d/100)%100,dd=d%100;return sys_days{year{y}/month{(unsigned)m}/day{(unsigned)dd}}.time_since_epoch().count();}
long long at(int d,int s){return dn(d)*86400LL+s;}
double hfri(int d,int s){int w=wd(d);if(w<1||w>5)return 0;return max(0.0,((5-w)*86400.0+FRI-s)/3600.0);}
struct Cfg{string n;double age;int dep;double hf,w;bool baseline;};
vector<Cfg> cfgs(){return{
{"CTRL_D8H36W2",0,8,36,2,true},
{"A3D4H36W2",3,4,36,2,false},{"A3D4H36W3",3,4,36,3,false},{"A3D4H36W4",3,4,36,4,false},{"A3D4H36W5",3,4,36,5,false},{"A3D4H36W8",3,4,36,8,false},
{"A2D4H36W2",2,4,36,2,false},{"A2D4H36W3",2,4,36,3,false},{"A2D4H36W5",2,4,36,5,false},
{"A3D3H36W2",3,3,36,2,false},{"A3D3H36W3",3,3,36,3,false},{"A3D3H36W5",3,3,36,5,false},
{"A3D4H48W2",3,4,48,2,false},{"A3D4H48W3",3,4,48,3,false},{"A3D4H48W5",3,4,48,5,false}
};}
struct B{bool a=false,esc=false;double z=0;int bu=0,se=0,mp=0,mn=0;double bs=0,ss=0,nextP=0,nextN=0,space=1;long long start=0;int sz()const{return bu+se;}};
double liq(const B&b,double bid,double ask){return b.a?(b.bu*bid-b.bs+b.ss-b.se*ask-COMM*b.sz()):0;}
struct DS{int date=0,baskets=0,wins=0,fri=0,orders=0,maxOpen=0,escapes=0;double pnl=0,minEq=1e100,maxM=0;bool target=false,mfail=false,afail=false;};
struct S{Cfg c;double bal=1000;bool alive=true,stop=false;B b;DS d;double rH=0,rL=0;bool rv=false,armed=false,inside=false;};
struct H{long long key=LLONG_MIN;double hi=-1e100,lo=1e100,lh=0,ll=0;bool v=false;};
void setR(S&s,const H&h,bool in){if(h.v){s.rH=h.lh;s.rL=h.ll;s.rv=true;s.inside=in;s.armed=!in;}}
void newDay(S&s,int d,double bid,double ask){s.d=DS();s.d.date=d;s.d.minEq=s.bal+liq(s.b,bid,ask);s.stop=false;}
void risk(S&s,double bid,double ask){if(!s.alive)return;double eq=s.bal+liq(s.b,bid,ask);s.d.minEq=min(s.d.minEq,eq);s.d.maxOpen=max(s.d.maxOpen,s.b.sz());s.d.maxM=max(s.d.maxM,s.b.sz()*((bid+ask)/2.0)/LEV);if(eq<=0){s.alive=false;s.d.afail=true;s.bal=0;}}
bool canAdd(const S&s,double bid,double ask){double eq=s.bal+liq(s.b,bid,ask);double m=(s.b.sz()+1)*((bid+ask)/2)/LEV;return eq>=m;}
void closeB(S&s,const H&h,double bid,double ask,bool win,bool fri){double q=liq(s.b,bid,ask);s.bal+=q;s.d.pnl+=q;if(win)s.d.wins++;if(fri)s.d.fri++;s.b=B();setR(s,h,true);if(s.bal<=0){s.bal=0;s.alive=false;s.d.afail=true;}if(s.d.pnl>=TARGET-1e-12){s.d.target=true;s.stop=true;}}
void startB(S&s,int side,int d,int sec,double bid,double ask){if(!canAdd(s,bid,ask)){s.alive=false;s.d.mfail=true;return;}s.b=B();s.b.a=true;s.b.z=bid;s.b.start=at(d,sec);double f=side==1?ask:bid;if(side==1){s.b.bu=1;s.b.bs=f;}else{s.b.se=1;s.b.ss=f;}s.d.baskets++;s.d.orders++;s.armed=false;risk(s,bid,ask);}
void add(S&s,int side,double bid,double ask){if(!canAdd(s,bid,ask)){s.alive=false;s.d.mfail=true;return;}double f=side==1?ask:bid;if(side==1){s.b.bu++;s.b.bs+=f;}else{s.b.se++;s.b.ss+=f;}s.d.orders++;risk(s,bid,ask);}
void maybeEsc(S&s,int d,int sec){if(!s.b.a||s.b.esc)return;int two=min(s.b.mp,-s.b.mn);double age=(at(d,sec)-s.b.start)/3600.0;bool trig=s.c.baseline?(two>=s.c.dep&&hfri(d,sec)<=s.c.hf):(age>=s.c.age&&two>=s.c.dep&&hfri(d,sec)<=s.c.hf);if(trig){s.b.esc=true;s.b.space=s.c.w;s.b.nextP=s.b.z+s.b.mp*GRID+s.b.space;s.b.nextN=s.b.z+s.b.mn*GRID-s.b.space;s.d.escapes++;}}
void esc(S&s,const H&h,double bid,double ask){double q;for(int g=0;g<256&&s.alive&&s.b.a;g++){int side=0;if(bid>=s.b.nextP)side=1;else if(bid<=s.b.nextN)side=-1;else break;q=liq(s.b,bid,ask);if(q>0){closeB(s,h,bid,ask,true,false);break;}add(s,side,bid,ask);if(!s.alive)break;if(side==1)s.b.nextP+=s.b.space;else s.b.nextN-=s.b.space;q=liq(s.b,bid,ask);if(s.d.pnl+q>=TARGET-1e-12){closeB(s,h,bid,ask,false,false);break;}}}
void tick(S&s,const H&h,int d,int sec,double bid,double ask){if(!s.alive)return;risk(s,bid,ask);if(!s.alive)return;int w=wd(d);if(w==0||w==6||s.stop)return;if(!s.b.a){if(!s.rv)return;if(s.inside){if(bid<=s.rH&&bid>=s.rL){s.inside=false;s.armed=true;}else return;}if(!s.armed)return;if(bid>s.rH)startB(s,1,d,sec,bid,ask);else if(bid<s.rL)startB(s,-1,d,sec,bid,ask);return;}double q=liq(s.b,bid,ask);if(s.d.pnl+q>=TARGET-1e-12){closeB(s,h,bid,ask,false,false);return;}maybeEsc(s,d,sec);if(s.b.esc){esc(s,h,bid,ask);return;}bool cp=bid>=s.b.z+(s.b.mp+1)*GRID,cn=bid<=s.b.z+(s.b.mn-1)*GRID;if(cp){while(s.alive&&s.b.a&&!s.b.esc&&bid>=s.b.z+(s.b.mp+1)*GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,h,bid,ask,true,false);break;}s.b.mp++;add(s,1,bid,ask);if(!s.alive)break;q=liq(s.b,bid,ask);if(s.d.pnl+q>=TARGET-1e-12){closeB(s,h,bid,ask,false,false);break;}maybeEsc(s,d,sec);}}else if(cn){while(s.alive&&s.b.a&&!s.b.esc&&bid<=s.b.z+(s.b.mn-1)*GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,h,bid,ask,true,false);break;}s.b.mn--;add(s,-1,bid,ask);if(!s.alive)break;q=liq(s.b,bid,ask);if(s.d.pnl+q>=TARGET-1e-12){closeB(s,h,bid,ask,false,false);break;}maybeEsc(s,d,sec);}}if(s.b.a&&s.b.esc)esc(s,h,bid,ask);}
void selftest(){vector<pair<double,int>>v={{1,1},{2,4},{2,4},{2,7},{2,7}};cout<<"name,net\n";for(int i=0;i<5;i++)cout<<"scenario"<<i+1<<","<<fixed<<setprecision(2)<<v[i].first-COMM*v[i].second<<"\n";}
int main(int ac,char**av){ios::sync_with_stdio(false);cin.tie(nullptr);if(ac>1&&string(av[1])=="--selftest"){selftest();return 0;}vector<S>ss;for(auto&c:cfgs()){S s;s.c=c;ss.push_back(s);}cout<<"config,date,pnl,target,margin_fail,account_fail,baskets,wins,friday,orders,max_open,escapes,min_equity,max_margin,balance\n";H h;string line;int d,sec,cd=0;double bid,ask,lb=0,la=0;bool have=false;while(getline(cin,line)){if(!parse(line,d,sec,bid,ask))continue;if(!have){have=true;cd=d;lb=bid;la=ask;for(auto&s:ss)newDay(s,d,bid,ask);}if(d!=cd){for(auto&s:ss){if(s.alive&&wd(cd)==5&&s.b.a)closeB(s,h,lb,la,false,true);auto&x=s.d;cout<<s.c.n<<","<<x.date<<","<<fixed<<setprecision(6)<<x.pnl<<","<<x.target<<","<<x.mfail<<","<<x.afail<<","<<x.baskets<<","<<x.wins<<","<<x.fri<<","<<x.orders<<","<<x.maxOpen<<","<<x.escapes<<","<<x.minEq<<","<<x.maxM<<","<<s.bal<<"\n";if(s.alive)newDay(s,d,bid,ask);else{s.d=DS();s.d.date=d;s.d.minEq=s.bal;}}cd=d;}lb=bid;la=ask;long long hk=(long long)d*24+sec/3600;bool hc=false;if(h.key==LLONG_MIN){h.key=hk;h.hi=bid;h.lo=bid;}else if(hk!=h.key){h.lh=h.hi;h.ll=h.lo;h.v=h.hi>h.lo;h.key=hk;h.hi=bid;h.lo=bid;hc=true;}else{h.hi=max(h.hi,bid);h.lo=min(h.lo,bid);}if(hc&&wd(d)>=1&&wd(d)<=5)for(auto&s:ss)if(s.alive&&!s.b.a&&!s.stop)setR(s,h,false);for(auto&s:ss)tick(s,h,d,sec,bid,ask);}if(have)for(auto&s:ss){if(s.alive&&wd(cd)==5&&s.b.a)closeB(s,h,lb,la,false,true);auto&x=s.d;cout<<s.c.n<<","<<x.date<<","<<fixed<<setprecision(6)<<x.pnl<<","<<x.target<<","<<x.mfail<<","<<x.afail<<","<<x.baskets<<","<<x.wins<<","<<x.fri<<","<<x.orders<<","<<x.maxOpen<<","<<x.escapes<<","<<x.minEq<<","<<x.maxM<<","<<s.bal<<"\n";}}
